     1|import React from 'react';
     2|import { Text, type StyleProp, type TextStyle } from 'react-native';
     3|
     4|/**
     5| * Sanitize React children that are about to be rendered inside a <View>.
     6| *
     7| * React Native crashes with "Unexpected text node: ... A text node cannot be
     8| * a child of a <View>" when a string or number ends up as a direct child of
     9| * a View. This helper wraps any stray primitive children in <Text>, drops
    10| * empty whitespace strings, ignores booleans/null/undefined, and recurses
    11| * into Fragments so deeply-nested fragment children are also sanitized.
    12| */
    13|export function renderSafeViewChildren(
    14|  children: React.ReactNode,
    15|  textStyle?: StyleProp<TextStyle>,
    16|): React.ReactNode {
    17|  return React.Children.map(children, (child) => {
    18|    if (child == null) {
    19|      return null;
    20|    }
    21|
    22|    if (typeof child === 'boolean') {
    23|      return null;
    24|    }
    25|
    26|    if (typeof child === 'string') {
    27|      return child.trim().length > 0 ? <Text style={textStyle}>{child}</Text> : null;
    28|    }
    29|
    30|    if (typeof child === 'number') {
    31|      if (!Number.isFinite(child)) {
    32|        return null;
    33|      }
    34|      return <Text style={textStyle}>{child}</Text>;
    35|    }
    36|
    37|    if (React.isValidElement<{ children?: React.ReactNode }>(child) && child.type === React.Fragment) {
    38|      return <>{renderSafeViewChildren(child.props.children, textStyle)}</>;
    39|    }
    40|
    41|    return child;
    42|  });
    43|}
